package bookstore

import (
	"fmt"
	"sort"
	"testing"
)

var price = [6]int{0, 800, 1520, 2160, 2560, 3000}

// dpCost is an exhaustive DP over sorted (descending) count vectors,
// considering every possible group (all 31 non-empty subsets of the 5 titles).
func dpCost(c [5]int) int {
	sort.Ints(c[:])
	for i, j := 0, 4; i < j; i, j = i+1, j-1 {
		c[i], c[j] = c[j], c[i] // descending
	}
	memo := map[[5]int]int{}
	var solve func(c [5]int) int
	solve = func(c [5]int) int {
		if v, ok := memo[c]; ok {
			return v
		}
		if c[0] == 0 {
			memo[c] = 0
			return 0
		}
		best := -1
		for mask := 1; mask < 32; mask++ {
			n := [5]int(c)
			s := 0
			ok := true
			for i := 0; i < 5; i++ {
				if mask&(1<<i) != 0 {
					if n[i] == 0 {
						ok = false
						break
					}
					n[i]--
					s++
				}
			}
			if !ok {
				continue
			}
			// re-sort the child before recursing so memo keys are canonical
			sort.Ints(n[:])
			for i, j := 0, 4; i < j; i, j = i+1, j-1 {
				n[i], n[j] = n[j], n[i]
			}
			cost := price[s] + solve(n)
			if best < 0 || cost < best {
				best = cost
			}
		}
		memo[c] = best
		return best
	}
	return solve(c)
}

// TestOpCheck cross-validates Cost against the exhaustive DP for every
// distinct sorted count vector (i.e. every possible basket shape) up to maxN.
func TestOpCheck(t *testing.T) {
	const maxN = 18
	bad, total := 0, 0
	var rec func(prefix [5]int, remaining int)
	rec = func(prefix [5]int, remaining int) {
		if remaining == 0 {
			total++
			if Cost(vecToBooks(prefix)) != dpCost(prefix) {
				bad++
				if bad <= 20 {
					fmt.Printf("MISMATCH %v layer=%d dp=%d\n", prefix, Cost(vecToBooks(prefix)), dpCost(prefix))
				}
			}
			return
		}
		// generate non-increasing 5-tuples: next value <= current last
		last := 5
		if len(prefix) > 0 {
			last = prefix[len(prefix)-1]
		}
		for v := last; v >= 0; v-- {
		 np := append(prefix, v)
			rec([5]int(np), remaining-1)
		}
	}
	_ = rec
	// simpler: iterate all non-increasing tuples by recursion on positions
	var gen func(pos int, maxVal int, cur *[5]int, left int)
	gen = func(pos int, maxVal int, cur *[5]int, left int) {
		if pos == 5 {
			if left == 0 {
				total++
				if Cost(vecToBooks(*cur)) != dpCost(*cur) {
					bad++
					if bad <= 20 {
						fmt.Printf("MISMATCH %v layer=%d dp=%d\n", *cur, Cost(vecToBooks(*cur)), dpCost(*cur))
					}
				}
			}
			return
		}
		for v := maxVal; v >= 0; v-- {
			if v > left {
				continue
			}
			cur[pos] = v
			gen(pos+1, v, cur, left-v)
		}
	}
	for n := 0; n <= maxN; n++ {
		var cur [5]int
		gen(0, n, &cur, n)
	}
	fmt.Printf("checked %d count-vectors, %d mismatches\n", total, bad)
	if bad > 0 {
		t.Errorf("%d mismatches found", bad)
	}
}

func vecToBooks(c [5]int) []int {
	var b []int
	for i, n := range c {
		for j := 0; j < n; j++ {
			b = append(b, i+1)
		}
	}
	return b
}

